13: /** 单独有界后台线程；准备与投递分开，重启不自动重放在途模型或渠道请求。 */
14: @Slf4j
15: @Component
16: @RequiredArgsConstructor
17: public class LifeReviewRuntime {
18:     private final LifeReviewRepository repository;
19:     private final LifeReviewService reviews;
20:     private final LifeOutreachService outreach;
21:     private final ResetBarrier barrier;
22:     private final Clock automationClock;
23:     @org.springframework.beans.factory.annotation.Autowired(required = false)
24:     private LifeCompanionService companion;
25:     private final ScheduledExecutorService worker = Executors.newSingleThreadScheduledExecutor(r -> {
26:         Thread t = new Thread(r, "life-review-worker"); t.setDaemon(true); return t;
27:     });
28:     private final ScheduledExecutorService generationWorker = Executors.newSingleThreadScheduledExecutor(r -> {
29:         Thread t = new Thread(r, "life-review-generation"); t.setDaemon(true); return t;
30:     });
31:     @EventListener(ApplicationReadyEvent.class)
32:     /** 迁移就绪后恢复未知状态，再启动有界后台循环。 */
33:     public void start() {
34:         if (!barrier.blocked()) try (var lease = barrier.enter()) {
35:             repository.migrateMailSecrets();
36:             repository.recover();
37:         }
38:         worker.scheduleWithFixedDelay(this::tick, 2, 2, TimeUnit.SECONDS);
39:         generationWorker.scheduleWithFixedDelay(this::generate, 2, 2, TimeUnit.SECONDS);
40:     }
41:     /** 按授权准备每日内容和到期候选，重置保护期间跳过。 */
42:     public void tick() {
43:         if (barrier.blocked()) return;
44:         try (var lease = barrier.enter()) {
45:             for (var s : repository.enabled()) {
46:                 try {
47:                     var local = automationClock.instant().atZone(ZoneId.of(s.timezone()));
48:                     int triggerHour = repository.habit(s.owner())
49:                             .filter(h -> h.active() && automationClock.instant().isBefore(h.expiresAt()))
50:                             .map(LifeReviewModels.Habit::availableHour)
51:                             .orElse(21);
52:                     if (local.getHour() >= triggerHour && repository.latest(s.owner(), local.toLocalDate()).isEmpty())
53:                         reviews.prepare(s.owner(), new LifeReviewDtos.Prepare(local.toLocalDate(), 0, false));
54:                     outreach.tick(s.owner());
55:                 } catch (RuntimeException e) { log.warn("生活复盘调度跳过：{}", e.getClass().getSimpleName()); }
56:             }
57:         } catch (RuntimeException e) { log.warn("生活复盘后台暂停：{}", e.getClass().getSimpleName()); }
58:     }
59:     /** 模型生成与主动陪伴学习使用独立单线程，避免等待模型期间阻塞现实信号监测。 */
60:     void generate() {
61:         if (barrier.blocked()) return;
62:         try {
63:             reviews.tick();
64:             if (companion != null) {
65:                 for (var s : repository.enabled()) {
66:                     try { companion.tick(s.owner()); }
67:                     catch (RuntimeException e) { log.warn("主动陪伴调度跳过：{}", e.getClass().getSimpleName()); }
68:                 }
69:             }
70:         }
71:         catch (RuntimeException e) { log.warn("生活复盘生成调度暂停：{}", e.getClass().getSimpleName()); }
72:     }
73:     @PreDestroy public void close() { worker.shutdownNow(); generationWorker.shutdownNow(); }
74: }

