149:     public void tick(String owner) {
150:         var s = authorization.require(owner);
151:         if (!s.proactive()) return;
152:         Instant now = automationClock.instant();
153:         repository.expire(owner, now);
154:         var local = now.atZone(ZoneId.of(s.timezone()));
155:         if (signals != null) signals.checkSignals(s, local, now);
156:         if (local.getHour() < 12 || !local.toLocalTime().isBefore(LocalTime.of(23, 30))) return;
157:         for (var c : repository.candidates(owner)) {
158:             if (!c.state().equals("PENDING")) continue;
159:             if (!now.isBefore(c.expiresAt())) {
160:                 repository.candidateState(owner, c.id(), "PENDING", "EXPIRED", null, ""); continue;
161:             }
162:             var content = repository.content(owner, c.contentId());
163:             if (content.isEmpty() || !LifeOutreachPolicy.isDeliverable(content.get())) {
164:                 repository.candidateState(owner, c.id(), "PENDING", "CANCELLED", null, ""); continue;
165:             }
166:             if (now.isBefore(due(c))) continue;
167:             // 冷启动：全域每日最多一次，同主题至少24小时；无新信息由唯一键阻止入队。
168:             if (repository.lastPresentation(owner).filter(sent -> now.isBefore(sent.plus(Duration.ofHours(24)))).isPresent()) continue;
169:             if (!repository.candidateState(owner, c.id(), "PENDING", "PRESENTED", now, "")) continue;
170:             if (s.feishu()) deliveries.sendCandidate(owner, c);
171:         }
172:         checkIdleNudge(s, local, now);
173:     }
174:     private void checkIdleNudge(Settings s, ZonedDateTime local, Instant now) {
175:         if (!s.idleCheckinEnabled()) return;
176:         if (companion != null && companion.view(s.owner()).companionEnabled()) return;
177:         int minHour = repository.habit(s.owner()).filter(h -> h.active() && now.isBefore(h.expiresAt()))
178:                 .map(Habit::availableHour).orElse(12);
179:         if (local.getHour() < minHour) return;
180:         if (repository.lastPresentation(s.owner()).filter(sent -> now.isBefore(sent.plus(Duration.ofHours(24)))).isPresent()) return;
181:         Instant lastActive = activity != null
182:                 ? activity.lastInteractionAt(s.owner(), local.getZone(), now).orElse(null)
183:                 : repository.latestUserActivity(s.owner()).orElse(null);
184:         Instant baseline = s.authorizedAt();
185:         if (lastActive != null && (baseline == null || lastActive.isAfter(baseline))) {
186:             baseline = lastActive;
187:         }
188:         if (baseline == null || Duration.between(baseline, now).toDays() < s.idleCheckinDays()) return;
189:         String dedupKey = "idle:" + baseline.truncatedTo(ChronoUnit.MINUTES);
190:         deliveries.sendNudge(s, "IDLE_CHECKIN", dedupKey, IDLE_CHECKIN_TEXT);
191:     }
192:     private void requireCapacity(String owner, String topic, String novelty) {
193:         if (repository.pendingCount(owner) >= 100 && !repository.candidateExists(owner, topic, novelty))
194:             throw new IllegalArgumentException("主动候选积压已达一百条，请先取消或等待过期");
195:     }
196:     private Instant due(Candidate c) {
197:         var s = repository.settings(c.owner());
198:         Instant base = LifeReviewService.availableAt(c.dueAt(), s.timezone());
199:         return repository.habit(c.owner()).filter(h -> h.active() && automationClock.instant().isBefore(h.expiresAt()))
200:                 .map(h -> {
201:                     var local = base.atZone(ZoneId.of(s.timezone()));
202:                     Instant preferred = local.toLocalDate().atTime(h.availableHour(), 0).atZone(local.getZone()).toInstant();
203:                     return preferred.isAfter(base) ? preferred : base;
204:                 }).orElse(base);
205:     }
206: }

