17: @RequiredArgsConstructor
18: public class ReviewRuntime {
19:     private final ReviewCoachService reviews;
20:     private final ReviewDeliveryService deliveries;
21:     private final ScheduledExecutorService worker = Executors.newSingleThreadScheduledExecutor(r -> {
22:         var thread = new Thread(r, "review-worker");
23:         thread.setDaemon(true);
24:         return thread;
25:     });
