30:     /** 数据库迁移完成后再启动，避免启动早期扫描。 */
31:     @EventListener(ApplicationReadyEvent.class)
32:     public void start() {
33:         worker.scheduleWithFixedDelay(() -> {
34:             if (resetBarrier.blocked()) return;
35:             try { reviews.tick(); } catch (RuntimeException exception) {
36:                 log.error("复盘工作项处理失败：{}", exception.getClass().getSimpleName());
37:             }
38:             try { deliveries.freezeReady(); } catch (RuntimeException exception) {
39:                 log.error("复盘邮件冻结失败：{}", exception.getClass().getSimpleName());
40:             }
41:         }, 5, 5, TimeUnit.SECONDS);
42:     }
